'use client'

import { useSound } from '@/hooks/use-sound'
import React, { useState } from 'react'

export function PintchSwitch() {
  const [isOn, setIsOn] = useState(false)

  const toggle = () => setIsOn(p => !p)

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault()
      toggle()
    }
  }

  const playClick = useSound("/audio/ui-sounds/toggle-2.mp3");

  return (
    <button
      role="switch"
      aria-checked={isOn}
      onClick={() => {
        toggle();
        playClick();
      }}
      onKeyDown={handleKeyDown}
      className={[
        'relative flex items-center',
        'w-[120px] h-[46px] rounded-full',
        'cursor-pointer outline-none select-none',
        'focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-neutral-400',
        'bg-[#e8e8e8] dark:bg-[#151518]',
        'shadow-[inset_3px_3px_7px_rgba(0,0,0,0.09),inset_-2px_-2px_5px_rgba(255,255,255,0.8)]',
        'dark:shadow-[inset_3px_3px_7px_rgba(0,0,0,0.5),inset_-2px_-2px_5px_rgba(50,50,65,0.35)]',
      ].join(' ')}
    >
      {/* Left dot — visible when ON */}
      <span
        aria-hidden="true"
        className={[
          'pointer-events-none absolute left-[13px]',
          'w-[5px] h-[5px] rounded-full',
          'bg-[#a8b8c4] dark:bg-[#607a8c]',
          'transition-opacity duration-300',
          isOn ? 'opacity-60' : 'opacity-0',
        ].join(' ')}
      />

      {/* Right dot — orange, visible when OFF */}
      <span
        aria-hidden="true"
        className={[
          'pointer-events-none absolute right-[13px]',
          'w-[5px] h-[5px] rounded-full',
          'bg-[#f05a00] dark:bg-[#ff6820]',
          'transition-opacity duration-300',
          isOn ? 'opacity-0' : 'opacity-100',
        ].join(' ')}
      />

      {/* Thumb */}
      <span
        aria-hidden="true"
        className={[
          'pointer-events-none absolute top-[3px] left-[3px]',
          'flex items-center justify-center gap-[4px]',
          'px-[3px] h-[40px] rounded-full',
          'bg-[#e5e5e5] dark:bg-[#2a2a32]',
          'transition-transform duration-300 ease-in-out',
          // Light: strong white top-highlight + soft bottom shadow
          // Dark: replace white highlights with low-opacity light tint; keep the bottom shadow heavy
          'shadow-[0_3px_10px_rgba(0,0,0,0.35),inset_0px_8px_8px_rgba(255,255,255,0.9),inset_2px_-1px_8px_rgba(0,0,0,0.12)]',
          'dark:shadow-[0_4px_12px_rgba(0,0,0,0.6),inset_0px_6px_8px_rgba(255,255,255,0.07),inset_0px_-4px_8px_rgba(0,0,0,0.55),inset_1px_1px_0px_rgba(255,255,255,0.06)]',
          isOn ? 'translate-x-[42px]' : 'translate-x-0',
        ].join(' ')}
      >
        {/* knob1 */}
        <span
          className={[
            'w-[31px] h-[31px] rounded-full',
            // Light: bright fill + crisp top-left highlight + soft inset shadow
            'bg-[#f0f0f0]',
            'shadow-[inset_2px_3px_6px_rgba(0,0,0,0.08),inset_-3px_-3px_8px_rgba(255,255,255,0.95),inset_-1px_-1px_0px_rgba(255,255,255,1)]',
            // Dark: muted slate fill; very subtle top-left light catch; strong bottom-right depression
            'dark:bg-[#3c3c48]',
            'dark:shadow-[inset_2px_3px_8px_rgba(0,0,0,0.55),inset_-2px_-2px_6px_rgba(255,255,255,0.055),inset_1px_1px_0px_rgba(255,255,255,0.04)]',
          ].join(' ')}
        />
        {/* knob2 */}
        <span
          className={[
            'w-[31px] h-[31px] rounded-full',
            'bg-[#f0f0f0]',
            'shadow-[inset_2px_3px_8px_rgba(0,0,0,0.12),inset_-4px_-4px_10px_rgba(255,255,255,1),inset_-2px_-2px_0px_rgba(255,255,255,1)]',
            'dark:bg-[#3c3c48]',
            'dark:shadow-[inset_2px_3px_8px_rgba(0,0,0,0.55),inset_-3px_-3px_8px_rgba(255,255,255,0.05),inset_-1px_-1px_0px_rgba(0,0,0,0.3)]',
          ].join(' ')}
        />
      </span>
    </button>
  )
}

export default PintchSwitch

/* Track: flat on-surface channel (inset only, no outer neumorphic raise) */
.track {
  box-shadow:
    inset 3px 3px 7px rgba(0, 0, 0, 0.09),
    inset -2px -2px 5px rgba(255, 255, 255, 0.8);
}

/* Thumb: prominently raised above the surface */
.thumb {}

/* Inner knob: raised pintch bump */
.knob {
  box-shadow:
    /* 0 3px 8px rgba(0, 0, 0, 0.18),
    0 1px 3px rgba(0, 0, 0, 0.12), */
    inset 0 1px 2px rgba(255, 255, 255, 0.95),
    inset 0 -1px 2px rgba(0, 0, 0, 0.08);
}

.knob1 {
  box-shadow:
    inset 3px 4px 14px 0px rgba(0, 0, 0, 0.1),
    inset -2px -2px 10px 0px rgba(255, 255, 255, 1),
    inset -1px -1px 0px 0px rgba(255, 255, 255, 1);
}

.knob2 {
  box-shadow:
    inset 3px 4px 14px 0px rgba(0, 0, 0, 0.15),
    inset -4px -4px 12px 1px rgba(255, 255, 255, 1),
    inset -2px -2px 0px 0px rgba(255, 255, 255, 1);
}

:global(.dark) .track {
  box-shadow:
    inset 3px 3px 7px rgba(0, 0, 0, 0.5),
    inset -2px -2px 5px rgba(50, 50, 65, 0.35);
}

:global(.dark) .thumb {
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.6),
    0 2px 6px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.07),
    inset 0 1px 2px rgba(255, 255, 255, 0.08);
}

:global(.dark) .knob {
  box-shadow:
    0 3px 8px rgba(0, 0, 0, 0.5),
    0 1px 3px rgba(0, 0, 0, 0.35),
    inset 0 1px 2px rgba(255, 255, 255, 0.1),
    inset 0 -1px 2px rgba(0, 0, 0, 0.3);
}

import { useCallback, useEffect, useRef } from "react";

/**
 * Custom React hook to load and play a sound from a given URL using the Web Audio API.
 *
 * This hook fetches the audio file at the specified URL, decodes it, and prepares it for playback.
 * It returns a `play` function that can be called to play the loaded sound.
 *
 * @param url - The URL of the audio file to load and play.
 * @returns A function that, when called, plays the loaded sound.
 *
 * @remarks
 * - If the Web Audio API is not supported in the browser, a warning is logged and playback is disabled.
 * - The audio context and buffer are managed internally using React refs.
 * - Errors during fetching or decoding the audio are logged to the console.
 *
 * @example
 * ```tsx
 * const playClick = useSound('/sounds/click.mp3');
 * // Later in an event handler:
 * playClick();
 * ```
 */
export function useSound(url: string) {
  const audioCtxRef = useRef<AudioContext | null>(null);
  const bufferRef = useRef<AudioBuffer | null>(null);

  useEffect(() => {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext })
        .webkitAudioContext;

    if (!AudioContextClass) {
      console.warn("Web Audio API is not supported in this browser.");
      return;
    }

    const audioCtx = new AudioContextClass();
    audioCtxRef.current = audioCtx;

    fetch(url)
      .then((res) => res.arrayBuffer())
      .then((data) => audioCtx.decodeAudioData(data))
      .then((decoded) => {
        bufferRef.current = decoded;
      })
      .catch((err) => {
        console.log(`Failed to load click sound from ${url}:`, err);
      });
  }, [url]);

  const play = useCallback((volume: number = 1) => {
    if (audioCtxRef.current && bufferRef.current) {
      const source = audioCtxRef.current.createBufferSource();
      const gainNode = audioCtxRef.current.createGain();

      source.buffer = bufferRef.current;
      gainNode.gain.value = volume;

      source.connect(gainNode);
      gainNode.connect(audioCtxRef.current.destination);
      source.start(0);
    }
  }, []);

  return play;
}
